import { PASSWORD, USERS, expect, expectStatus, test } from "../../fixtures";

test.describe("sign out", () => {
  test("signing out clears the session cookie", { tag: "@AUTH-06" }, async ({ request }) => {
    // Arrange: sign in so the request context holds the session cookie.
    const login = await request.post("/api/auth/login", {
      data: { email: USERS.member, password: PASSWORD },
    });
    await expectStatus(login, 200);

    // Act
    const response = await request.post("/api/auth/logout");

    // Assert
    expect(response.status()).toBe(204);
    const setCookie = response
      .headersArray()
      .filter((h) => h.name.toLowerCase() === "set-cookie")
      .map((h) => h.value)
      .find((value) => value.startsWith("session="));
    expect(setCookie, "logout should send a Set-Cookie for session").toBeDefined();
    const lower = setCookie!.toLowerCase();
    const expired = lower.includes("max-age=0") || lower.includes("expires=thu, 01 jan 1970");
    expect(expired, `session cookie should be expired, got: ${setCookie}`).toBe(true);
  });
});
